 68	func discoverCapabilityHelpers(t *testing.T) []capabilityHelper {
 69		t.Helper()
 70	
 71		dir := findAgentDir(t)
 72		fset := token.NewFileSet()
 73		//nolint:staticcheck // ParseDir intentionally scans every production file regardless of build tags.
 74		pkgs, err := parser.ParseDir(fset, dir, func(info os.FileInfo) bool {
 75			return !strings.HasSuffix(info.Name(), "_test.go")
 76		}, 0)
