 82		for _, pkg := range pkgs {
 83			for _, file := range pkg.Files {
 84				for _, decl := range file.Decls {
 85					fn, ok := decl.(*ast.FuncDecl)
 86					if !ok || fn.Recv != nil || !isCapabilityHelperName(fn.Name.Name) {
