106	func capabilityResolver(fn *ast.FuncDecl) (string, string) {
107		if fn.Body == nil || len(fn.Body.List) != 1 {
108			return "", ""
109		}
110		ret, ok := fn.Body.List[0].(*ast.ReturnStmt)
111		if !ok || len(ret.Results) != 1 {
112			return "", ""
113		}
114		call, ok := ret.Results[0].(*ast.CallExpr)
115		if !ok {
116			return "", ""
117		}
118	
119		resolver, typeArg := indexedCall(call.Fun)
120		if resolver == nil || typeArg == nil {
121			return "", ""
122		}
123		capability, ok := typeArg.(*ast.Ident)
124		if !ok {
125			return resolver.Name, ""
126		}
127		return resolver.Name, capability.Name
128	}
129	
130	func indexedCall(expr ast.Expr) (*ast.Ident, ast.Expr) {
131		switch indexed := expr.(type) {
132		case *ast.IndexExpr:
133			resolver, ok := indexed.X.(*ast.Ident)
134			if !ok {
135				return nil, nil
136			}
137			return resolver, indexed.Index
138		case *ast.IndexListExpr:
139			resolver, ok := indexed.X.(*ast.Ident)
140			if !ok || len(indexed.Indices) != 1 {
141				return nil, nil
142			}
143			return resolver, indexed.Indices[0]
144		default:
145			return nil, nil
146		}
147	}
