200	// TestAgentPackages_NoForbiddenImports verifies that agent implementation packages
201	// (claudecode, codex, opencode, cursor, etc.) only import from allowed packages.
202	//
203	// This prevents agent implementations from coupling to framework internals
204	// (strategy, checkpoint, session, commands, hook_registry, lifecycle) which
205	// would create brittle dependencies that break when internals change.
206	//
207	// Agents should depend only on:
208	//   - The agent contract package (agent, agent/types, agent/testutil)
209	//   - Utility packages (logging, paths, jsonutil, textutil, transcript, etc.)
210	//   - Standard library and external dependencies
211	func TestAgentPackages_NoForbiddenImports(t *testing.T) {
212		t.Parallel()
213	
214		const repoPrefix = "github.com/entireio/cli/cmd/entire/cli/"
215	
216		// Packages that agent implementations must NOT import.
217		// These are framework internals that agents should be decoupled from.
218		forbiddenSuffixes := []string{
219			"strategy",
220			"checkpoint",
221			"session",
222			"commands",
223		}
224	
225		// Individual files in the cli package that agents must not depend on.
226		// We check for the cli package import itself since these are all in
227		// the top-level cli package (not sub-packages).
228		forbiddenCLIPackage := repoPrefix[:len(repoPrefix)-1] // "github.com/entireio/cli/cmd/entire/cli"
229	
230		// Packages within the repo that agents ARE allowed to import.
231		allowedPrefixes := []string{
232			repoPrefix + "agent",      // agent contract + sub-packages
233			repoPrefix + "gitrepo",    // repository layout utilities
234			repoPrefix + "logging",    // logging utilities
235			repoPrefix + "paths",      // path utilities
236			repoPrefix + "entiredir",  // the shared .entire root; the only sanctioned way to read or write there
237			repoPrefix + "osroot",     // traversal-resistant os.Root helpers, used with the above
238			repoPrefix + "jsonutil",   // JSON utilities
239			repoPrefix + "textutil",   // text utilities
240			repoPrefix + "transcript", // transcript utilities
241			repoPrefix + "trailers",   // git trailer utilities
242			repoPrefix + "stringutil", // string utilities
243			repoPrefix + "telemetry",  // telemetry
244			repoPrefix + "validation", // validation utilities
245			repoPrefix + "settings",   // settings (read-only access)
246			repoPrefix + "review",     // review env contract + AgentReviewer types (used by per-agent reviewer.go files)
247			repoPrefix + "testutil",   // canonical isolated repository fixtures for agent tests
248		}
249	
250		// Imports allowed in ONE agent package, keyed by its directory name.
251		// Unlike allowedPrefixes, an entry here does not widen the contract for
252		// every agent: it is one agent's answer to one agent's problem, and a
253		// second agent that wants it has to say so here first.
254		scopedPrefixes := map[string][]string{
255			"antigravity": {
256				// Cross-process advisory locks. agy fires its title command on
257				// every state change without serializing, so the title-tee takes
258				// a per-conversation flock around its dedup-and-append. No other
259				// agent's transport has that shape.
260				repoPrefix + "internal/flock",
261			},
262		}
263	
264		agentDir := findAgentDir(t)
265		agentPkgs := discoverAgentPackages(t, agentDir)
266	
267		if len(agentPkgs) == 0 {
268			t.Fatal("no agent packages found — test setup is broken")
269		}
270	
271		for _, pkgDir := range agentPkgs {
272			pkgName := filepath.Base(pkgDir)
273			t.Run(pkgName, func(t *testing.T) {
274				t.Parallel()
275				// Clone, don't append onto allowedPrefixes: appending would write
276				// this package's scoped entries into that slice's backing array
277				// whenever it has spare capacity, handing every package checked
278				// afterwards the exception scopedPrefixes exists to contain. It
279				// holds today only because allowedPrefixes is a literal whose cap
280				// equals its len; that is not a property to depend on.
281				allowedHere := append(slices.Clone(allowedPrefixes), scopedPrefixes[pkgName]...)
282				imports := extractImports(t, pkgDir)
283				for _, imp := range imports {
284					if !strings.HasPrefix(imp, repoPrefix) && imp != forbiddenCLIPackage {
285						continue // external or stdlib — allowed
286					}
287	
288					// Check if it's the top-level cli package itself
289					if imp == forbiddenCLIPackage {
290						t.Errorf("forbidden import %q — agent packages must not import the top-level cli package directly", imp)
291						continue
292					}
293	
294					// Check forbidden suffixes
295					rel := strings.TrimPrefix(imp, repoPrefix)
296					isForbidden := false
297					for _, forbidden := range forbiddenSuffixes {
298						if rel == forbidden || strings.HasPrefix(rel, forbidden+"/") {
299							t.Errorf("forbidden import %q — agent packages must not import %s internals", imp, forbidden)
300							isForbidden = true
301						}
302					}
303					if isForbidden {
304						continue
305					}
306	
307					// Check it's in the allowed list, or scoped to this package
308					allowed := false
309					for _, prefix := range allowedHere {
310						if imp == prefix || strings.HasPrefix(imp, prefix+"/") {
311							allowed = true
312							break
313						}
314					}
315					if !allowed {
316						t.Errorf("unexpected internal import %q — if every agent may use it, add it to allowedPrefixes in architecture_test.go; "+
317							"if it answers this agent's problem alone, add it to scopedPrefixes[%q] with the reason", imp, pkgName)
318					}
319				}
320			})
321		}
322	}
