336	// discoverAgentPackages finds all subdirectories of the agent dir that contain
337	// Go files, excluding "types" and "testutil" (those are contract/shared packages).
338	func discoverAgentPackages(t *testing.T, agentDir string) []string {
339		t.Helper()
340	
341		skipDirs := map[string]bool{
342			"types":          true, // contract types, not an agent implementation
343			"testutil":       true, // shared test utilities
344			"external":       true, // external agent adapter, not a self-registering agent
345			"skilldiscovery": true, // shared capability helper (registries, match), not an agent
346		}
347	
348		entries, err := os.ReadDir(agentDir)
349		if err != nil {
350			t.Fatalf("ReadDir(%s): %v", agentDir, err)
351		}
352	
353		var pkgs []string
354		for _, e := range entries {
355			if !e.IsDir() || skipDirs[e.Name()] {
356				continue
357			}
358			dir := filepath.Join(agentDir, e.Name())
359			// Only include if it has Go files
360			goFiles, err := filepath.Glob(filepath.Join(dir, "*.go"))
361			if err != nil {
362				t.Fatalf("filepath.Glob(%s): %v", dir, err)
363			}
364			if len(goFiles) > 0 {
365				pkgs = append(pkgs, dir)
366			}
367		}
368		return pkgs
369	}
