430	func hasInitWithRegister(t *testing.T, dir string) bool {
431		t.Helper()
432	
433		fset := token.NewFileSet()
434		// See extractImports for why this scan uses ParseDir.
435		pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool { //nolint:staticcheck // Intentionally scan files regardless of build tags.
436			return !strings.HasSuffix(fi.Name(), "_test.go")
437		}, 0)
