// Pre-PR implementations, copied verbatim from upstream/main 5893658fc.

func oldSidecar(ag Agent) (SidecarImageProvider, bool) {
	if ag == nil {
		return nil, false
	}
	p, ok := ag.(SidecarImageProvider)
	return p, ok
}

func oldLate(ag Agent) (LateTranscriptWriter, bool) {
	if ag == nil {
		return nil, false
	}
	lw, ok := ag.(LateTranscriptWriter)
	if !ok {
		return nil, false
	}
	if _, isDeclarer := ag.(CapabilityDeclarer); isDeclarer {
		return nil, false
	}
	return lw, true
}

func oldOOB(ag Agent) (OutOfBandTokenSource, bool) {
	if ag == nil {
		return nil, false
	}
	src, ok := ag.(OutOfBandTokenSource)
	if !ok {
		return nil, false
	}
	if _, isDeclarer := ag.(CapabilityDeclarer); isDeclarer {
		return nil, false
	}
	return src, true
}

func oldStreaming(ag Agent) (StreamingTextGenerator, bool) {
	if ag == nil {
		return nil, false
	}
	stg, ok := ag.(StreamingTextGenerator)
	if !ok {
		return nil, false
	}
	if cd, ok := ag.(CapabilityDeclarer); ok {
		return stg, cd.DeclaredCapabilities().StreamingTextGenerator
	}
	return stg, true
}

func oldInjector(ag Agent) (ContextInjector, bool) {
	if ag == nil {
		return nil, false
	}
	ci, ok := ag.(ContextInjector)
	return ci, ok
}

func oldLister(ag Agent) (ModelLister, bool) {
	if ag == nil {
		return nil, false
	}
	ml, ok := ag.(ModelLister)
	return ml, ok
}

func oldPerm(ag Agent) (PermissionConfigOwner, bool) {
	owner, ok := ag.(PermissionConfigOwner)
	return owner, ok
}

// Non-declarer agents for the capabilities whose existing stubs are declarers.
type blastBuiltinLister struct{ mockBaseAgent }

func (blastBuiltinLister) ListModels(context.Context) ([]ModelInfo, error) { return nil, nil }

type blastBuiltinPerm struct{ mockBaseAgent }

func (*blastBuiltinPerm) PermissionConfig(context.Context) (*HookConfigFile, error) {
	return &HookConfigFile{}, nil
}

// outcome records everything a caller can observe: panic, ok, nil-ness, and dynamic value.
func outcome[T any](f func(Agent) (T, bool), ag Agent) (s string) {
	defer func() {
		if r := recover(); r != nil {
			s = "panic"
		}
	}()
	v, ok := f(ag)
	return fmt.Sprintf("ok=%v val=%#v", ok, any(v))
}

func TestBlastEquivalence(t *testing.T) {
	full := func(c DeclaredCaps) Agent { return &mockFullAgent{caps: c} }
	agents := map[string]Agent{
		"nil":                     nil,
		"typed-nil base":          (*mockBaseAgent)(nil),
		"typed-nil full":          (*mockFullAgent)(nil),
		"base":                    &mockBaseAgent{},
		"full declares none":      full(DeclaredCaps{}),
		"full declares streaming": full(DeclaredCaps{StreamingTextGenerator: true}),
		"builtin streaming":       &mockBuiltinStreamingAgent{},
		"builtin OOB":             &mockBuiltinOOBAgent{},
		"builtin late writer":     &mockBuiltinLateWriterAgent{},
		"injector (builtin)":      injectorStub{},
		"injector (declarer)":     declaredInjectorStub{},
		"lister (builtin)":        blastBuiltinLister{},
		"lister (declarer)":       modelListerStub{},
		"perm (builtin)":          &blastBuiltinPerm{},
		"perm (declarer)":         &mockPermissionConfigOwner{},
	}

	type pair struct {
		name     string
		old, new func(Agent) string
	}
	pairs := []pair{
		{"Sidecar", func(a Agent) string { return outcome(oldSidecar, a) }, func(a Agent) string { return outcome(AsSidecarImageProvider, a) }},
		{"Late", func(a Agent) string { return outcome(oldLate, a) }, func(a Agent) string { return outcome(AsLateTranscriptWriter, a) }},
		{"OOB", func(a Agent) string { return outcome(oldOOB, a) }, func(a Agent) string { return outcome(AsOutOfBandTokenSource, a) }},
		{"Streaming", func(a Agent) string { return outcome(oldStreaming, a) }, func(a Agent) string { return outcome(AsStreamingTextGenerator, a) }},
		{"Injector", func(a Agent) string { return outcome(oldInjector, a) }, func(a Agent) string { return outcome(AsContextInjector, a) }},
		{"Lister", func(a Agent) string { return outcome(oldLister, a) }, func(a Agent) string { return outcome(AsModelLister, a) }},
		{"Perm", func(a Agent) string { return outcome(oldPerm, a) }, func(a Agent) string { return outcome(AsPermissionConfigOwner, a) }},
	}

	checked, positives := 0, 0
	for _, p := range pairs {
		for name, ag := range agents {
			o, n := p.old(ag), p.new(ag)
			checked++
			if len(o) > 7 && o[:7] == "ok=true" {
				positives++
			}
			if o != n {
				t.Errorf("%s / %s: old %s, new %s", p.name, name, o, n)
			}
		}
	}
	t.Logf("compared %d helper×agent cases (%d where old returned ok=true); all identical", checked, positives)
}

